import {
  Calendar as AriaCalendar,
  ButtonContext,
  CalendarCell,
  CalendarGrid,
  CalendarGridBody,
  CalendarGridHeader,
  CalendarHeaderCell,
  CalendarHeading,
  CalendarMonthPicker,
  CalendarYearPicker,
  useSlottedContext,
} from "react-aria-components";
import type {
  CalendarProps as AriaCalendarProps,
  DateValue,
} from "react-aria-components";
import { ChevronLeft, ChevronRight } from "./icons";
import type { ReactNode, Ref } from "react";
import { Button } from "./Button";
import { Select, SelectItem } from "./Select";
import "./Calendar.css";

/**
 * Month-nav button. Reads its accessible name from React Aria's `previous`/`next`
 * slot context instead of hardcoding one.
 *
 * React Aria already supplies a **localized** name there (`useCalendarBase` →
 * `stringFormatter.format("previous" | "next")` — `이전`/`다음` in ko-KR, and exactly
 * `Previous`/`Next` in en-US). A literal `aria-label` on the Button would silently beat
 * it: `useContextProps` merges as `mergeProps(contextProps, props)` and a defined prop
 * always wins, so every locale would be pinned to English — borrowed a11y, un-borrowed
 * by hand. The name has to be read and re-passed rather than simply omitted, because
 * `isIconOnly` requires an accessible name at **compile time** (component-contract §2)
 * and TypeScript cannot see one arriving through context. The literals below are only
 * the no-context fallback.
 *
 * A child component, not a hook in `Calendar` itself: the slot context is provided
 * *inside* `AriaCalendar`, so a hook called above it would read nothing.
 */
function CalendarNavButton({
  slot,
  children,
}: {
  slot: "previous" | "next";
  children: ReactNode;
}) {
  const context = useSlottedContext(ButtonContext, slot);
  return (
    <Button
      variant="ghost"
      size="medium"
      isIconOnly
      slot={slot}
      className="sd-calendar__navigation"
      aria-label={
        context?.["aria-label"] ?? (slot === "previous" ? "Previous" : "Next")
      }
    >
      {children}
    </Button>
  );
}

export interface CalendarProps
  extends Omit<AriaCalendarProps<DateValue>, "className" | "children"> {
  /**
   * Header navigation treatment.
   *
   * @default "buttons"
   */
  navigation?: "buttons" | "dropdown";
  /** Additional class. sd-calendar is always preserved. */
  className?: string;
  /** Forwarded to the root calendar DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function Calendar({
  navigation = "buttons",
  className,
  ref,
  ...props
}: CalendarProps) {
  return (
    <AriaCalendar
      {...props}
      ref={ref}
      className={className ? `sd-calendar ${className}` : "sd-calendar"}
    >
      {/* div, not <header>: a <header> is an implicit `banner` landmark, which is
          page-scoped — a calendar's own month-nav must not register as a page banner
          (axe landmark-banner-is-top-level). Class unchanged. */}
      <div className="sd-calendar__header">
        <CalendarNavButton slot="previous">
          <ChevronLeft aria-hidden size="1em" />
        </CalendarNavButton>
        {navigation === "dropdown" ? (
          <div className="sd-calendar__picker-group">
            {/* Month/year pickers reuse the DS Select. RAC's *Picker render prop yields the
                collection as `{items, value, onChange}` (RAC's own names); Select speaks RAC's
                `selectedKey`/`onSelectionChange`, so map value→selectedKey, onChange→
                onSelectionChange, and drive the options from `items`. Registry dependency. */}
            <CalendarMonthPicker format="long">
              {({ items, value, onChange, "aria-label": ariaLabel }) => (
                <Select
                  aria-label={ariaLabel}
                  size="medium"
                  selectedKey={value}
                  onSelectionChange={onChange}
                  isDisabled={props.isDisabled}
                  items={items}
                >
                  {(item) => (
                    <SelectItem id={(item as { id: number }).id}>
                      {(item as { formatted: string }).formatted}
                    </SelectItem>
                  )}
                </Select>
              )}
            </CalendarMonthPicker>
            <CalendarYearPicker>
              {({ items, value, onChange, "aria-label": ariaLabel }) => (
                <Select
                  aria-label={ariaLabel}
                  size="medium"
                  selectedKey={value}
                  onSelectionChange={onChange}
                  isDisabled={props.isDisabled}
                  items={items}
                >
                  {(item) => (
                    <SelectItem id={(item as { id: number }).id}>
                      {(item as { formatted: string }).formatted}
                    </SelectItem>
                  )}
                </Select>
              )}
            </CalendarYearPicker>
          </div>
        ) : (
          <CalendarHeading className="sd-calendar__heading sd-type-title-medium" />
        )}
        <CalendarNavButton slot="next">
          <ChevronRight aria-hidden size="1em" />
        </CalendarNavButton>
      </div>
      <CalendarGrid className="sd-calendar__grid" weekdayStyle="short">
        <CalendarGridHeader>
          {(day) => (
            <CalendarHeaderCell className="sd-calendar__weekday sd-type-label-medium">
              {day}
            </CalendarHeaderCell>
          )}
        </CalendarGridHeader>
        <CalendarGridBody>
          {(date) => (
            <CalendarCell date={date} className="sd-calendar__cell sd-type-body-medium" />
          )}
        </CalendarGridBody>
      </CalendarGrid>
    </AriaCalendar>
  );
}

.sd-calendar {
  display: inline-flex;
  flex-direction: column;
  gap: var(--sd-calendar-gap);
  width: max-content;
  color: var(--sd-calendar-foreground);
}

.sd-calendar__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sd-calendar-header-gap);
}

.sd-calendar__navigation:dir(rtl) {
  scale: -1 1;
}

.sd-calendar__heading {
  color: var(--sd-calendar-heading-foreground);
}

/* Month/year pickers are DS Select instances; their look is owned by Select. The group only
   lays them out side by side. */
.sd-calendar__picker-group {
  display: flex;
  align-items: center;
  gap: var(--sd-calendar-picker-group-gap);
}

.sd-calendar__grid {
  border-spacing: var(--sd-calendar-grid-border-spacing);
  /* Keep the grid at its intrinsic 7 × cell-size, centred under whatever the header needs.
     Without this the table is a stretched flex item: `navigation="dropdown"` makes the header
     (two Selects + both nav buttons) wider than the grid, `width: max-content` on the root
     hands that width to every child, and an auto-layout table absorbs it by widening its
     COLUMNS — but the day cells are fixed-size divs inside those columns, so they stay
     left-packed while the centred weekday headers drift right (measured: root 324.78, columns
     46.39, cells still 40). The column/day misalignment was the visible symptom. */
  align-self: center;
}

.sd-calendar__weekday {
  width: var(--sd-calendar-cell-size);
  height: var(--sd-calendar-weekday-height);
  color: var(--sd-calendar-weekday-foreground);
  text-align: center;
}

.sd-calendar__cell {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--sd-calendar-cell-size);
  height: var(--sd-calendar-cell-size);
  color: var(--sd-calendar-cell-foreground);
  border-radius: var(--sd-calendar-cell-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  /* The wash each state lays over the cell: the surface wash, or on a selected day's fill the one
     named for its ink, which goes away from that ink (contrast-contract.mjs § the state layer). */
  --sd-calendar-cell-state-hover-current: var(--sd-state-hover);
  --sd-calendar-cell-state-pressed-current: var(--sd-state-pressed);
  text-align: center;
  cursor: pointer;
  outline: none;
}

.sd-calendar__cell::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-calendar__cell[data-hovered]::after {
  background: var(--sd-calendar-cell-state-hover-current);
}
.sd-calendar__cell[data-pressed]::after {
  background: var(--sd-calendar-cell-state-pressed-current);
}

.sd-calendar__cell[data-selected] {
  background: var(--sd-calendar-cell-background-selected);
  color: var(--sd-calendar-cell-foreground-selected);
  --sd-calendar-cell-state-hover-current: var(--sd-state-hover-on-accent);
  --sd-calendar-cell-state-pressed-current: var(--sd-state-pressed-on-accent);
}

.sd-calendar__cell[data-today] {
  box-shadow: inset 0 0 0 var(--sd-calendar-cell-border-width-today) var(--sd-calendar-cell-border-today);
}

.sd-calendar__cell[data-selected][data-today] {
  box-shadow: inset 0 0 0 var(--sd-calendar-cell-border-width-today) var(--sd-calendar-cell-border-selected-today);
}

/* React Aria disables a day outside the shown month (it never takes hover or press), so this ink is
   a disabled one and owes no contrast under the wash; the selector says so. */
.sd-calendar__cell[data-outside-month][data-disabled] {
  color: var(--sd-calendar-cell-foreground-outside-month);
}

.sd-calendar__cell[data-unavailable],
.sd-calendar__cell[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-calendar__cell[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-calendar__cell[data-today][data-focus-visible] {
  /* today keeps its inset under focus. If this and the plain focus rule were both (0,2,0) with the
     focus rule later, a focused TODAY would lose its marker entirely. */
  box-shadow:
    inset 0 0 0 var(--sd-calendar-cell-border-width-today) var(--sd-calendar-cell-border-today),
    0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-calendar__cell[data-selected][data-today][data-focus-visible] {
  /* the only combination that draws the SELECTED today inset. Keyed on
     `[data-selected][data-focus-visible]` alone, every selected focused date would wear a today
     marker whether or not it was today. A selected non-today
     cell wants the plain ring, which the base focus rule gives it, so no rule for that case. */
  box-shadow:
    inset 0 0 0 var(--sd-calendar-cell-border-width-today) var(--sd-calendar-cell-border-selected-today),
    0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
